<?php elseif(in_array($page,['login','register'])): ?><section class="inner section-wrap form-wrap"><p class="overline">THE REBA COMMUNITY</p><h1><?= $page==='login'?'Welcome back':'Join the society' ?><span class="italic">.</span></h1><p class="intro"><?= $page==='login'?'Sign in to see your orders and continue your story.':'Make an account to save your details and keep track of orders.' ?></p><?php if($error): ?><div class="error" role="alert"><?= e($error) ?></div><?php endif; ?><form method="post" class="form-stack"><?= field() ?><input type="hidden" name="action" value="<?= e($page) ?>"><input type="hidden" name="next" value="<?= e($_GET['next']??$_POST['next']??'') ?>"><?php if($page==='register'): ?><label>Full name<input name="name" required maxlength="100" autocomplete="name" value="<?= e($_POST['name']??'') ?>"></label><?php endif; ?><label>Email address<input type="email" name="email" required maxlength="254" autocomplete="email" value="<?= e($_POST['email']??'') ?>"></label><label>Password<input type="password" name="password" required minlength="10" autocomplete="<?= $page==='login'?'current-password':'new-password' ?>"><?php if($page==='register'): ?><small>At least 10 characters.</small><?php endif; ?></label><button class="button dark"><?= $page==='login'?'Sign in':'Create account' ?> <?= icon('arrow') ?></button></form><p class="form-switch"><?= $page==='login'?'New to Reba?':'Already a member?' ?> <a href="<?= e(url($page==='login'?'register':'login', ['next'=>$_GET['next']??$_POST['next']??''])) ?>"><?= $page==='login'?'Create an account':'Sign in' ?> ↗</a></p></section>
<?php elseif($page==='checkout'): if(!$user) { go('login'); } ?><section class="inner section-wrap form-wrap"><p class="overline">ALMOST THERE</p><h1>Checkout<span class="italic">.</span></h1><p class="intro">Tell us where your books should go.</p><div class="info-box">This submits an order request only. No payment is collected online; prices and delivery charges require confirmation.</div><?php if($error): ?><div class="error"><?= e($error) ?></div><?php endif; ?><form method="post" class="form-stack"><?= field() ?><input type="hidden" name="action" value="checkout"><label>Phone number<input name="phone" required maxlength="20" autocomplete="tel" value="<?= e($_POST['phone']??'') ?>"></label><label>Full delivery address<textarea name="address" required minlength="10" maxlength="1000" rows="4" autocomplete="street-address"><?= e($_POST['address']??'') ?></textarea></label><button class="button dark">Place order request <?= icon('arrow') ?></button></form><p class="small"><a href="<?= e(url('cart')) ?>">← Return to bag</a></p></section>
<?php elseif($page==='account'): if(!$user) go('login'); $orders=db(function(&$d) use($user){return array_reverse(array_values(array_filter($d['orders'],fn($o)=>$o['user_id']===$user['id'])));}); ?><section class="inner section-wrap narrow"><div class="account-heading"><div><p class="overline">YOUR LITTLE CORNER</p><h1>Hello, <?= e(explode(' ',$user['name'])[0]) ?><span class="italic">.</span></h1><p class="intro"><?= e($user['email']) ?></p></div><form method="post"><?= field() ?><input type="hidden" name="action" value="logout"><button class="button outline">Sign out</button></form></div><h2>Your orders</h2><?php if(!$orders): ?><div class="empty">No orders yet. Your next favourite book is waiting. <a href="<?= e(url('shop')) ?>">Explore books ↗</a></div><?php else: foreach($orders as $order): ?><article class="order"><div class="order-head"><div><strong>Order #<?= e($order['id']) ?></strong><p><?= e(date('j M Y',strtotime($order['date']))) ?></p></div><span class="status"><?= e($order['status']) ?></span></div><?php foreach($order['items'] as $item): ?><p><?= e($item['title']) ?> × <?= (int)$item['qty'] ?> <span class="right"><?= money($item['price']*$item['qty']) ?></span></p><?php endforeach; ?><div class="order-total">Indicative subtotal <strong><?= money($order['total']) ?></strong></div><p class="small">No payment collected. Delivery and final prices require confirmation.</p></article><?php endforeach; endif; ?></section>
<?php elseif($page==='about'): ?><section class="inner section-wrap about-page"><p class="overline">HELLO FROM KOLKATA</p><h1>For the love of<br><em>the written word.</em></h1><div class="about-grid"><div class="about-block"><img class="about-logo" src="<?= e(asset('reba-logo.png')) ?>" alt="Reba Book Society"><p>INDEPENDENT BOOKSELLER<br>COLLEGE STREET, KOLKATA</p></div><div><h2>A little about us.</h2><p>Reba Book Society is a publisher and bookseller located in College Street, Kolkata—a place where a love of books is always close at hand.</p><p>We believe the best books stay with you. From timeless literature to poetry and drama, our shelves are made for readers, collectors and the endlessly curious.</p><div id="visit"><p class="overline">COME SAY HELLO</p><h2>Find us on College Street.</h2><p>College Street, Kolkata, West Bengal, India</p></div><a class="button dark" href="<?= e(url('shop')) ?>">Explore our books <?= icon('arrow') ?></a></div></div></section>
<?php elseif($page==='contact'): ?><section class="inner section-wrap narrow"><p class="overline">GET IN TOUCH &nbsp; / &nbsp; REBA BOOK SOCIETY</p><h1>Contact us<span class="italic">.</span></h1><p class="intro">Find Reba Book Society on College Street, Kolkata, West Bengal, India.</p><div class="info-box">Our email address, phone number and exact shop address will be added here once confirmed.</div><a class="button outline" href="<?= e(url('about')) ?>#visit">More about our bookshop <?= icon('arrow') ?></a></section>
<?php else: http_response_code(404); ?><section class="inner section-wrap narrow"><h1>Page not found<span class="italic">.</span></h1><p>Let’s get you back to the books.</p><a class="button dark" href="<?= e(url()) ?>">Back home <?= icon('arrow') ?></a></section><?php endif; ?>
